import type { SanityClient } from '@sanity/client';
import { type WorkflowConfig, type WorkflowDeployment, type WorkflowInstance, type WorkflowResource } from '@sanity/workflow-engine';
import type { EngineScope } from './operation-args.ts';
export interface DeploymentContext {
    deployment: WorkflowDeployment;
    client: SanityClient;
}
export interface InstanceContext {
    client: SanityClient;
    /** The engine scope derived from the instance itself — `{tag, workflowResource}`
     *  ready to pass straight to an engine verb, so callers never re-assemble it. */
    scope: EngineScope;
    /** The located instance. Already fetched by the fan-out to derive the scope,
     *  so a command that needs its state reuses it rather than re-fetching —
     *  set-stage's stage picker reads the pinned definition snapshot and
     *  `currentStage`; nuke's instance mode reads the terminal state. */
    instance: WorkflowInstance;
}
/** Resolve the selected deployment. Deploy, definition-diff, and blueprint provision compare
 *  its acknowledgement with submitted definitions; selection alone must not assert a floor. */
export declare function resolveContext(flags: {
    deployment?: string | undefined;
    tag?: string | undefined;
}): Promise<DeploymentContext>;
/** One resource a read inspects, with its authenticated client. */
export interface ReadTarget {
    resource: WorkflowResource;
    client: SanityClient;
}
/**
 * The resolution every READ shares: an authenticated client per resource to
 * inspect — and nothing more. A read lists/inspects whatever is in the
 * Content Lake, so it must NOT inherit a deployment's tag or definition set
 * as a filter. The config only locates the resources here; the command
 * applies the user's explicit `--tag` (if any) as a query filter itself.
 *
 * Untagged, this is every distinct resource the config mentions — a read is
 * harmless to fan out, so "show me what's deployed" spans the whole config.
 * `--tag` narrows to the resources deployed under that tag (tags may repeat
 * across deployments). The token resolves once for the run, however many
 * targets it spans.
 */
export declare function resolveReadTargets(flags: {
    tag?: string | undefined;
}): Promise<ReadTarget[]>;
/** Distinct resources, keyed by their resource-shaped GDR (`<type>:<id>`).
 *  The first occurrence wins its position, so a caller-ordered list (e.g. the
 *  engine resource first) keeps its lead entry. */
export declare function dedupeResources(resources: WorkflowResource[]): WorkflowResource[];
/** The distinct resources a read targets: every resource deployed under the
 *  tag (tags may repeat across deployments), or — untagged — every distinct
 *  one the config's deployments mention ({@link dedupeResources}). */
export declare function resolveReadResources(config: WorkflowConfig, tag: string | undefined): WorkflowResource[];
/**
 * The resolution an instance-id-targeted command shares, read or write: locate
 * the instance by the same cross-resource fan-out the read/list commands use
 * ({@link findInstance}), then hand back an authenticated client for the
 * resource that held it plus a scope whose `tag` comes from the instance
 * itself — never from the config's declared deployments. An instance id is
 * globally unique and carries its own `tag`, so naming one is enough to act on
 * it: the config only locates candidate resources, and the fan-out's
 * {@link soleHitOrFail} rejects the collision case where several datasets hold
 * the id (the `<tag>.` fast-path may skip that full-set check — safe, ids are
 * collision-free). `--deployment` / `--tag` stay optional narrowers, not
 * required disambiguators.
 *
 * Contrast {@link resolveContext}: the deploy/diff/delete path IS scoped to a
 * declared deployment because it acts on the authored definition set (or a
 * definition name, which — unlike an instance id — isn't unique across tags).
 */
export declare function resolveInstanceContext(flags: {
    deployment?: string | undefined;
    tag?: string | undefined;
}, instanceId: string): Promise<InstanceContext>;
/** An instance located without interpreting its shape — the resource that held
 *  it and the {@link InstanceStamps} a delete gates on. */
export interface InstanceStampsContext {
    resource: WorkflowResource;
    stamps: InstanceStamps;
}
/**
 * Locate an instance by the same fan-out and `<tag>.` fast-path as
 * {@link resolveInstanceContext}, but reading only a projection — for the one
 * caller that must not be refused by the reader-floor gate. See
 * {@link findInstanceStamps} for why `nuke --instance` is that caller.
 *
 * Returns no client: a projection cannot be acted on through an engine verb, so
 * the caller builds its own write clients from the deployment it resolves.
 */
export declare function resolveInstanceStamps(flags: {
    deployment?: string | undefined;
    tag?: string | undefined;
}, instanceId: string): Promise<InstanceStampsContext>;
/** A read target that turned out to hold the instance being looked up. */
export interface InstanceHit extends ReadTarget {
    instance: WorkflowInstance;
}
/**
 * The sole cross-resource hit, or fail listing every holding resource —
 * ambiguity across datasets must error, never pick. `subject` names the
 * thing being looked up in the diagnostic (`Instance <id>`, `Definition "x"`).
 */
export declare function soleHitOrFail<T extends {
    resource: WorkflowResource;
}>(hits: T[], subject: string): T | undefined;
/**
 * Look an instance id up across every read target, reading each hit as a full
 * engine-gated instance document — the locate every command that then acts
 * through an engine verb uses. See {@link findAcrossTargets} for the
 * one-hit-wins semantics.
 */
export declare function findInstance({ targets, instanceId, requestTag, }: {
    targets: ReadTarget[];
    instanceId: string;
    requestTag: string;
}): Promise<InstanceHit | undefined>;
/**
 * The four persisted fields a delete needs to decide it may proceed, read
 * WITHOUT interpreting the document's shape: `_type` to prove it is an engine
 * instance and not co-located content, `tag` to locate the owning deployment,
 * and the terminal stamps to prove it has settled.
 */
export interface InstanceStamps {
    _type: string;
    tag?: string;
    completedAt?: string;
    abortedAt?: string;
}
